import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import test from "node:test";

import {
  ConfigLoadError,
  LoadOpenAiApiKey,
  LoadRealtimeAgentConfig,
} from "../../../src/agent/src/config.js";
import {
  FindRepositoryRoot,
  GetDefaultRealtimeAgentPaths,
  ResolveRepositoryPath,
} from "../../../src/agent/src/repo_paths.js";

function CreateFakeRepoRoot(): string
{
  const repoRoot = mkdtempSync(path.join(os.tmpdir(), "realtime-agent-repo-"));
  mkdirSync(path.join(repoRoot, "config"), { recursive: true });
  mkdirSync(path.join(repoRoot, "structure"), { recursive: true });
  writeFileSync(path.join(repoRoot, "config", "services.json"), "{}");
  return repoRoot;
}

test("FindRepositoryRoot locates the repository from a nested path", () =>
{
  const repoRoot = CreateFakeRepoRoot();
  const nested = path.join(repoRoot, "projects", "realtime-agent", "src");

  try
  {
    mkdirSync(nested, { recursive: true });
    assert.equal(FindRepositoryRoot(nested), repoRoot);
  }
  finally
  {
    rmSync(repoRoot, { recursive: true, force: true });
  }
});

test("GetDefaultRealtimeAgentPaths resolves repository-relative locations", () =>
{
  const repoRoot = CreateFakeRepoRoot();

  try
  {
    const paths = GetDefaultRealtimeAgentPaths(repoRoot);

    assert.equal(
      paths.defaultPromptFile,
      path.join(
        repoRoot,
        "projects/realtime-agent/prompts/system-prompts/basic_realtime_conversation_v1.md",
      ),
    );
    assert.equal(
      paths.databasePath,
      path.join(repoRoot, "data/realtime-agent/realtime-agent.sqlite"),
    );
    assert.equal(
      paths.runtimeLogPath,
      path.join(repoRoot, "logs/realtime-agent/realtime-agent.jsonl"),
    );
    assert.equal(
      ResolveRepositoryPath("data/realtime-agent/realtime-agent.sqlite", repoRoot),
      paths.databasePath,
    );
  }
  finally
  {
    rmSync(repoRoot, { recursive: true, force: true });
  }
});

test("LoadRealtimeAgentConfig merges config file values with defaults", async () =>
{
  const repoRoot = CreateFakeRepoRoot();
  const configPath = path.join(repoRoot, "config", "realtime-agent.json");

  try
  {
    await writeFile(
      configPath,
      JSON.stringify({
        model: "custom-model",
        default_prompt_file: "projects/realtime-agent/prompts/custom.md",
      }),
    );

    const config = await LoadRealtimeAgentConfig({ repoRoot, configPath });

    assert.equal(config.model, "custom-model");
    assert.equal(
      config.defaultPromptPath,
      path.join(repoRoot, "projects/realtime-agent/prompts/custom.md"),
    );
    assert.equal(
      config.databasePath,
      path.join(repoRoot, "data/realtime-agent/realtime-agent.sqlite"),
    );
    assert.equal(
      config.runtimeLogPath,
      path.join(repoRoot, "logs/realtime-agent/realtime-agent.jsonl"),
    );
  }
  finally
  {
    rmSync(repoRoot, { recursive: true, force: true });
  }
});

test("LoadOpenAiApiKey reads openai_api_key from config/api_keys.json", async () =>
{
  const repoRoot = CreateFakeRepoRoot();
  const apiKeysPath = path.join(repoRoot, "config", "api_keys.json");

  try
  {
    await writeFile(apiKeysPath, JSON.stringify({ openai_api_key: "repo-key" }));

    const apiKey = await LoadOpenAiApiKey({ repoRoot, apiKeysPath });
    assert.equal(apiKey, "repo-key");
  }
  finally
  {
    rmSync(repoRoot, { recursive: true, force: true });
  }
});

test("LoadOpenAiApiKey reports actionable error when key is missing", async () =>
{
  const repoRoot = CreateFakeRepoRoot();
  const apiKeysPath = path.join(repoRoot, "config", "api_keys.json");

  try
  {
    await assert.rejects(
      () => LoadOpenAiApiKey({ repoRoot, apiKeysPath }),
      (error: Error) =>
      {
        assert.ok(error instanceof ConfigLoadError);
        return error.message.includes("config/api_keys.json");
      },
    );
  }
  finally
  {
    rmSync(repoRoot, { recursive: true, force: true });
  }
});

import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export interface RealtimeAgentPaths
{
  configFile: string;
  apiKeysFile: string;
  defaultPromptFile: string;
  databasePath: string;
  runtimeLogPath: string;
}

const x_configRelative = "config/realtime-agent.json";
const x_apiKeysRelative = "config/api_keys.json";
const x_defaultPromptRelative =
  "projects/realtime-agent/prompts/system-prompts/basic_realtime_conversation_v1.md";
const x_databaseRelative = "data/realtime-agent/realtime-agent.sqlite";
const x_runtimeLogRelative = "logs/realtime-agent/realtime-agent.jsonl";

const x_moduleDir =
  typeof __dirname === "string"
    ? __dirname
    : path.dirname(fileURLToPath(import.meta.url));

export function FindRepositoryRoot(startPath?: string): string | undefined
{
  const startDir = path.resolve(startPath ?? process.cwd());
  let current = startDir;

  while (current !== path.dirname(current))
  {
    const servicesJsonPath = path.join(current, "config", "services.json");
    const structureDir = path.join(current, "structure");

    if (existsSync(servicesJsonPath) && existsSync(structureDir))
    {
      return current;
    }

    current = path.dirname(current);
  }

  return undefined;
}

export function ResolveRepositoryPath(relativePath: string, root?: string): string
{
  const repoRoot = root ?? FindRepositoryRoot(x_moduleDir) ?? FindRepositoryRoot();

  if (repoRoot === undefined)
  {
    throw new Error("repository root not found");
  }

  return path.join(repoRoot, relativePath);
}

export function GetDefaultRealtimeAgentPaths(root?: string): RealtimeAgentPaths
{
  const repoRoot = root ?? FindRepositoryRoot(x_moduleDir) ?? FindRepositoryRoot();

  if (repoRoot === undefined)
  {
    throw new Error("repository root not found");
  }

  return {
    configFile: path.join(repoRoot, x_configRelative),
    apiKeysFile: path.join(repoRoot, x_apiKeysRelative),
    defaultPromptFile: path.join(repoRoot, x_defaultPromptRelative),
    databasePath: path.join(repoRoot, x_databaseRelative),
    runtimeLogPath: path.join(repoRoot, x_runtimeLogRelative),
  };
}

export {
  x_apiKeysRelative,
  x_configRelative,
  x_databaseRelative,
  x_defaultPromptRelative,
  x_runtimeLogRelative,
};

import { readFile } from "node:fs/promises";

import {
  FindRepositoryRoot,
  GetDefaultRealtimeAgentPaths,
  ResolveRepositoryPath,
  x_databaseRelative,
  x_defaultPromptRelative,
} from "./repo_paths.js";
import {
  DEFAULT_REALTIME_MODEL,
} from "./types.js";

const x_logsDirRelative = "logs/realtime-agent";
const x_dataDirRelative = "data/realtime-agent";

export interface RealtimeAgentConfig
{
  model: string;
  data_dir: string;
  database_path: string;
  logs_dir: string;
  default_prompt_file: string;
  updated_at?: string;
  version?: number;
}

export interface ResolvedRealtimeAgentConfig extends RealtimeAgentConfig
{
  configFile: string;
  databasePath: string;
  defaultPromptPath: string;
  logsDir: string;
  runtimeLogPath: string;
}

export interface LoadRealtimeAgentConfigOptions
{
  configPath?: string;
  repoRoot?: string;
}

export interface LoadOpenAiApiKeyOptions
{
  apiKeysPath?: string;
  repoRoot?: string;
}

export class ConfigLoadError extends Error
{
  constructor(message: string)
  {
    super(message);
    this.name = "ConfigLoadError";
  }
}

function RequireRepoRoot(repoRoot?: string): string
{
  const resolved = repoRoot ?? FindRepositoryRoot();
  if (resolved === undefined)
  {
    throw new ConfigLoadError("repository root not found");
  }

  return resolved;
}

function BuildDefaultConfig(repoRoot: string): ResolvedRealtimeAgentConfig
{
  const paths = GetDefaultRealtimeAgentPaths(repoRoot);

  return {
    model: DEFAULT_REALTIME_MODEL,
    data_dir: x_dataDirRelative,
    database_path: x_databaseRelative,
    logs_dir: x_logsDirRelative,
    default_prompt_file: x_defaultPromptRelative,
    configFile: paths.configFile,
    databasePath: paths.databasePath,
    defaultPromptPath: paths.defaultPromptFile,
    logsDir: ResolveRepositoryPath(x_logsDirRelative, repoRoot),
    runtimeLogPath: paths.runtimeLogPath,
  };
}

function ResolveConfigPaths(
  config: RealtimeAgentConfig,
  repoRoot: string,
  configFile: string,
  runtimeLogPath: string,
): ResolvedRealtimeAgentConfig
{
  return {
    ...config,
    configFile,
    databasePath: ResolveRepositoryPath(config.database_path, repoRoot),
    defaultPromptPath: ResolveRepositoryPath(config.default_prompt_file, repoRoot),
    logsDir: ResolveRepositoryPath(config.logs_dir, repoRoot),
    runtimeLogPath,

import { readdir } from "node:fs/promises";
import { join } from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const packageRoot = join(fileURLToPath(new URL("..", import.meta.url)));
const testRoot = join(packageRoot, "dist", "tests", "agent");

async function CollectTestFiles(directory)
{
  const entries = await readdir(directory, { withFileTypes: true });
  const files = [];

  for (const entry of entries)
  {
    const entryPath = join(directory, entry.name);

    if (entry.isDirectory())
    {
      files.push(...await CollectTestFiles(entryPath));
    }
    else if (entry.isFile() && entry.name.endsWith(".test.js"))
    {
      files.push(entryPath);
    }
  }

  return files;
}

const testFiles = await CollectTestFiles(testRoot);

if (testFiles.length === 0)
{
  console.error(`No compiled test files found under ${testRoot}`);
  process.exit(1);
}

const result = spawnSync(process.execPath, ["--test", ...testFiles], {
  stdio: "inherit",
});

process.exit(result.status ?? 1);

